#include "darc_internal.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>

static int pathcmp(const void*a,const void*b){const DarcFlatEnt*x=a,*y=b;size_t nx=strlen(x->path),ny=strlen(y->path),m=nx<ny?nx:ny;int c=memcmp(x->path,y->path,m);return c?c:(nx<ny?-1:nx>ny?1:0);}
static int push(DarcFlatTree*t,DarcFlatEnt*e){if(t->n==t->cap){size_t nc=t->cap?t->cap*2:128;DarcFlatEnt*v=darc_realloc(t->v,nc*sizeof*v);if(!v)return -1;t->v=v;t->cap=nc;}t->v[t->n++]=*e;memset(e,0,sizeof*e);return 0;}
void darc_flat_free(DarcFlatTree*t){if(t->v)for(size_t i=0;i<t->n;i++){free(t->v[i].path);free(t->v[i].target);}free(t->v);memset(t,0,sizeof*t);}
DarcFlatEnt*darc_flat_find(DarcFlatTree*t,const char*path){size_t lo=0,hi=t->n;while(lo<hi){size_t m=lo+(hi-lo)/2;int c=strcmp(t->v[m].path,path);if(c<0)lo=m+1;else hi=m;}return lo<t->n&&!strcmp(t->v[lo].path,path)?&t->v[lo]:NULL;}
static int load_file_meta(const char*repo,DarcFlatEnt*e){DarcObject o;int rc=darc_object_load(repo,&e->cid,&o,1);if(rc)return rc;if(o.type!=OBJ_FILE){darc_object_free(&o);return DARC_E_CORRUPT;}DarcFileObj f;if(darc_file_parse(o.payload.data,o.payload.len,&f)){darc_object_free(&o);return DARC_E_CORRUPT;}e->logical_size=f.logical_size;memcpy(e->file_digest,f.digest,32);darc_file_free(&f);darc_object_free(&o);return 0;}
static int rec_tree(const char*repo,const DarcCid*tcid,const char*prefix,DarcFlatTree*out,size_t depth){if(depth>4096)return DARC_E_CORRUPT;DarcObject o;int rc=darc_object_load(repo,tcid,&o,1);if(rc)return rc;if(o.type!=OBJ_TREE){darc_object_free(&o);return DARC_E_CORRUPT;}DarcTreeObj t;if(darc_tree_parse(o.payload.data,o.payload.len,&t)){darc_object_free(&o);return DARC_E_CORRUPT;}darc_object_free(&o);for(size_t i=0;i<t.n;i++){DarcTreeEnt*te=&t.e[i];char*name=darc_strndup((const char*)te->name,te->name_len);if(!name){rc=DARC_E_IO;break;}char*path=prefix&&*prefix?darc_path_join(prefix,name):darc_strdup(name);free(name);if(!path){rc=DARC_E_IO;break;}DarcFlatEnt e;memset(&e,0,sizeof e);e.path=path;e.type=te->type;e.mode=te->mode;e.mtime_ns=te->mtime_ns;e.cid=te->cid;e.hardlink_group=te->hardlink_group;if(te->target_len){e.target=darc_malloc(te->target_len);if(!e.target){free(path);rc=DARC_E_IO;break;}memcpy(e.target,te->target,te->target_len);e.target_len=te->target_len;}if(e.type==1){rc=load_file_meta(repo,&e);if(rc){free(e.path);free(e.target);break;}}DarcCid child=e.cid;uint8_t typ=e.type;if(push(out,&e)){free(e.path);free(e.target);rc=DARC_E_IO;break;}if(typ==2){rc=rec_tree(repo,&child,path,out,depth+1);if(rc)break;}}
 darc_tree_free(&t);return rc;}
int darc_flatten_snapshot(const char*repo,const DarcSnapshotObj*snap,DarcFlatTree*out){memset(out,0,sizeof*out);int rc=rec_tree(repo,&snap->root,"",out,0);if(rc){darc_flat_free(out);return rc;}if(out->n>1)qsort(out->v,out->n,sizeof*out->v,pathcmp);for(size_t i=0;i<out->n;i++)if(out->v[i].type==4){char*target=darc_strndup((const char*)out->v[i].target,out->v[i].target_len);if(!target){darc_flat_free(out);return DARC_E_IO;}DarcFlatEnt*p=darc_flat_find(out,target);free(target);if(!p||(p->type!=1&&p->type!=4)){darc_flat_free(out);return DARC_E_CORRUPT;}if(p->type==4){/* topology canonicalization requires target primary, so chain is corruption */darc_flat_free(out);return DARC_E_CORRUPT;}out->v[i].cid=p->cid;out->v[i].logical_size=p->logical_size;memcpy(out->v[i].file_digest,p->file_digest,32);}return 0;}
int darc_path_is_safe_archive(const char*p){if(!p||!*p||p[0]=='/')return 0;const char*s=p;while(*s){const char*q=strchr(s,'/');size_t n=q?(size_t)(q-s):strlen(s);if(n==0||(n==1&&s[0]=='.')||(n==2&&s[0]=='.'&&s[1]=='.')||memchr(s,0,n)==NULL){/* memchr condition deliberately not used: C path has terminator beyond n */}if(n==0||(n==1&&s[0]=='.')||(n==2&&s[0]=='.'&&s[1]=='.'))return 0;if(!q)break;s=q+1;}return 1;}
char*darc_xml_escape(const uint8_t*s,size_t n){DarcBuf b;darc_buf_init(&b);for(size_t i=0;i<n;i++){const char*r=NULL;size_t l=0;switch(s[i]){case '&':r="&amp;";l=5;break;case '<':r="&lt;";l=4;break;case '>':r="&gt;";l=4;break;case '"':r="&quot;";l=6;break;case '\'':r="&apos;";l=6;break;default:break;}if(r){if(darc_buf_put(&b,r,l))goto bad;}else if(s[i]>=0x20||s[i]=='\n'||s[i]=='\t'){if(darc_buf_u8(&b,s[i]))goto bad;}else {char z[8];int m=snprintf(z,sizeof z,"&#x%02X;",s[i]);if(darc_buf_put(&b,z,(size_t)m))goto bad;}}if(darc_buf_u8(&b,0))goto bad;return (char*)b.data;bad:darc_buf_free(&b);return NULL;}

static int hdr(const char*p,DarcRhEnt*h){uint8_t b[32];int fd=open(p,O_RDONLY|O_CLOEXEC);if(fd<0)return -1;size_t o=0;while(o<32){ssize_t z=read(fd,b+o,32-o);if(z<0){if(errno==EINTR)continue;close(fd);return -1;}if(!z){close(fd);return -1;}o+=(size_t)z;}close(fd);if(memcmp(b,"DARCOBJ1",8)||darc_rd_u16(b+10)||darc_rd_u32(b+28)!=darc_crc32c(b+8,20)||b[8]<1||b[8]>5||b[9]>1)return -1;memset(h,0,sizeof*h);h->type=b[8];h->codec=b[9];h->uncomp_len=darc_rd_u64(b+12);h->stored_len=darc_rd_u64(b+20);h->used=1;return 0;}
int darc_list_objects(const char*repo,DarcDiskList*out,bool tolerate){memset(out,0,sizeof*out);char*root=darc_path_join(repo,"objects/sha256");if(!root)return DARC_E_IO;DIR*d=opendir(root);if(!d){free(root);return DARC_E_IO;}struct dirent*a;while((a=readdir(d))){if(a->d_name[0]=='.'||strlen(a->d_name)!=2)continue;char*dir=darc_path_join(root,a->d_name);if(!dir){closedir(d);free(root);darc_disklist_free(out);return DARC_E_IO;}DIR*dd=opendir(dir);if(!dd){free(dir);continue;}struct dirent*b;while((b=readdir(dd))){if(b->d_name[0]=='.'||strlen(b->d_name)!=62)continue;char hex[65];memcpy(hex,a->d_name,2);memcpy(hex+2,b->d_name,62);hex[64]=0;DarcCid cid;if(darc_hex_cid(hex,&cid)){if(!tolerate){closedir(dd);free(dir);closedir(d);free(root);darc_disklist_free(out);return DARC_E_CORRUPT;}continue;}char*p=darc_path_join(dir,b->d_name);if(!p){closedir(dd);free(dir);closedir(d);free(root);darc_disklist_free(out);return DARC_E_IO;}DarcRhEnt h;int bad=hdr(p,&h);if(bad&&!tolerate){free(p);closedir(dd);free(dir);closedir(d);free(root);darc_disklist_free(out);return DARC_E_CORRUPT;}if(out->n==out->cap){size_t nc=out->cap?out->cap*2:256;DarcDiskObj*v=darc_realloc(out->v,nc*sizeof*v);if(!v){free(p);closedir(dd);free(dir);closedir(d);free(root);darc_disklist_free(out);return DARC_E_IO;}out->v=v;out->cap=nc;}out->v[out->n].cid=cid;out->v[out->n].h=h;out->v[out->n].path=p;if(bad)memset(&out->v[out->n].h,0,sizeof h);out->n++;}closedir(dd);free(dir);}closedir(d);free(root);return 0;}
void darc_disklist_free(DarcDiskList*l){if(l->v)for(size_t i=0;i<l->n;i++)free(l->v[i].path);free(l->v);memset(l,0,sizeof*l);}
